  rt::Task<std::pair<json::value,json::value>> quota(std::shared_ptr<Harness> harness,std::string id){auto windowReading=harness->kv->get(p::apiKeyUsageV3WindowKey(harness->policy));const auto window=co_await std::move(windowReading);auto requestReading=harness->kv->get(p::apiKeyUsageV3RequestKey(harness->policy,id));const auto request=co_await std::move(requestReading);ASSERT(!window.value.isNullish());ASSERT(!request.value.isNullish());co_return std::make_pair(window.value.toJson(),request.value.toJson());}
